class LmdbBackupPublicationTest {

	private record Commit(long transactionId, long previousTransactionId, List<LmdbBackupDeltaCodec.Record> records) {
	}

	private static List<Commit> capture(LmdbStore store) {
		List<Commit> commits = new ArrayList<>();
		store.getBackingStore().setCommitListener(new LmdbSailStore.CommitListener() {
			@Override
			public void onCommit(long transactionId, long previousRequiredTxn,
					List<LmdbBackupDeltaCodec.Record> records) {
				commits.add(new Commit(transactionId, previousRequiredTxn, records));
			}

			@Override
			public void onCommitFailure(long transactionId, long previousRequiredTxn,
					List<LmdbBackupDeltaCodec.Record> records, Throwable error) {
				throw new AssertionError(error);
			}
		});
		return commits;
	}

	@Test
	void publishesMixedSinksOnceAndRecoversNamespacePredecessor(@TempDir Path directory) throws Exception {
		long boundary;
		LmdbStore store = new LmdbStore(directory.toFile());
		store.init();
		try {
			List<Commit> commits = capture(store);
			long baseline = store.getBackingStore().getCurrentCommittedTxnId();
			var vf = SimpleValueFactory.getInstance();
			try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(vf.createIRI("urn:explicit"), vf.createIRI("urn:p"), vf.createLiteral("value"));
				connection.addInferredStatement(vf.createIRI("urn:inferred"), vf.createIRI("urn:p"),
						vf.createLiteral("value"));
				connection.setNamespace("prefix", "urn:namespace:");
				connection.commit();
				assertEquals(1, commits.size());
				Commit mixed = commits.getFirst();
				assertEquals(baseline, mixed.previousTransactionId());
				assertEquals(3, mixed.records().size());
				assertEquals(1, mixed.records()
						.stream()
						.filter(record -> record.isStatementOperation() && record.isExplicit())
						.count());
				assertEquals(1, mixed.records()
						.stream()
						.filter(record -> record.isStatementOperation() && !record.isExplicit())
						.count());
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.setNamespace("rolled-back", "urn:rollback:");
				connection.rollback();
				assertEquals(1, commits.size());
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.setNamespace("second", "urn:second:");
				connection.commit();
				assertEquals(2, commits.size());
				assertEquals(mixed.transactionId(), commits.getLast().previousTransactionId());
				boundary = commits.getLast().transactionId();
				assertEquals(boundary, store.getBackingStore().getCurrentCommittedTxnId());
			}
		} finally {
			store.shutDown();
		}
		store = new LmdbStore(directory.toFile());
		store.init();
		try {
			assertEquals(boundary, store.getBackingStore().getCurrentCommittedTxnId());
			List<Commit> commits = capture(store);
			try (var connection = store.getConnection()) {
				connection.begin();
				connection.setNamespace("reopened", "urn:reopened:");
				connection.commit();
			}
			assertEquals(1, commits.size());
			assertEquals(boundary, commits.getFirst().previousTransactionId());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void capturesNoneCheckpointRemovals(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile());
		store.init();
		try {
			List<Commit> commits = capture(store);
			var vf = SimpleValueFactory.getInstance();
			var subject = vf.createIRI("urn:subject");
			var predicate = vf.createIRI("urn:predicate");
			var object = vf.createLiteral("value");
			try (var connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.addStatement(subject, predicate, object);
				connection.commit();
				assertEquals(1, commits.size());
				connection.begin(IsolationLevels.NONE);
				connection.removeStatements(subject, predicate, object);
				connection.commit();
				assertEquals(2, commits.size());
				assertEquals(1, commits.getLast().records().size());
				assertFalse(commits.getLast().records().getFirst().isAddition());
				assertEquals(commits.getFirst().transactionId(), commits.getLast().previousTransactionId());
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void retainsFailedPublicationAsPredecessorAfterReopen(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile());
		store.init();
		List<Long> failed = new ArrayList<>();
		try {
			store.getBackingStore().setCommitListener(new LmdbSailStore.CommitListener() {
				@Override
				public void onCommit(long transactionId, long previousRequiredTxn,
						List<LmdbBackupDeltaCodec.Record> records) {
					throw new IllegalStateException("Simulated journal write failure");
				}

				@Override
				public void onCommitFailure(long transactionId, long previousRequiredTxn,
						List<LmdbBackupDeltaCodec.Record> records, Throwable error) {
					failed.add(transactionId);
				}
			});
			try (var connection = store.getConnection()) {
				connection.begin();
				connection.setNamespace("failed", "urn:failed:");
				connection.commit();
			}
			assertEquals(1, failed.size());
			assertEquals(failed.getFirst().longValue(), store.getBackingStore().getCurrentCommittedTxnId());
		} finally {
			store.shutDown();
		}
		store = new LmdbStore(directory.toFile());
		store.init();
		try {
			List<Commit> commits = capture(store);
			try (var connection = store.getConnection()) {
				connection.begin();
				connection.setNamespace("later", "urn:later:");
				connection.commit();
			}
			assertEquals(1, commits.size());
			assertEquals(failed.getFirst().longValue(), commits.getFirst().previousTransactionId());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void readsLegacyAndChainedJournalFormats() throws Exception {
		var record = new LmdbBackupDeltaCodec.Record(LmdbBackupDeltaCodec.NamespaceOperation.SET, "p", "urn:p:");
		ByteArrayOutputStream legacy = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.write(legacy, List.of(record));
		assertEquals(-1L, LmdbBackupDeltaCodec.readJournal(new ByteArrayInputStream(legacy.toByteArray()))
				.previousTransactionId());
		ByteArrayOutputStream chained = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.write(chained, List.of(record), 37L);
		var journal = LmdbBackupDeltaCodec.readJournal(new ByteArrayInputStream(chained.toByteArray()));
		assertEquals(37L, journal.previousTransactionId());
		assertEquals(1, journal.records().size());
		assertEquals("urn:p:", journal.records().getFirst().getNamespaceName());
		assertTrue(LmdbBackupDeltaCodec.read(new ByteArrayInputStream(chained.toByteArray()))
				.getFirst()
				.isNamespaceOperation());
	}
}
